import React from 'react';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Box,
  Card,
  CardContent,
  Chip,
  Stack,
  Typography,
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';

export interface Iso14064Methodology {
  gwpBasis?: string;
  quantificationApproach?: string;
  reportingMode?: string;
  carbonModelVersion?: string;
  factorRegistryVersion?: string;
  tdLoss?: {
    lossRate?: number;
    lossPercent?: number;
    application?: string;
    formula?: string;
    period?: string;
    basis?: string;
    source?: string;
    alsoCitedIn?: string;
    renewableAddOnKg?: number;
    appliedToFuels?: boolean;
  };
  feraModeling?: {
    enabled?: boolean;
    electricitySystemLossRate?: number;
    rationale?: string;
    reference?: string;
    doubleCountingPrevention?: string;
  };
  standardsReferenced?: Array<{ id?: string; title?: string; published?: string }>;
  limitations?: string[];
}

export interface Iso14064BiogenicDisclosure {
  reportedSeparately?: boolean;
  treatment?: string;
  biogenicTransactionCount?: number;
  note?: string;
}

export interface Iso14064CategorySummary {
  standard?: string;
  clause?: string;
  dualReportingNote?: string;
  categories?: Array<{
    id?: string;
    label?: string;
    clause?: string;
    ghgProtocolMapping?: string;
    tco2e?: number;
    subcategories?: Array<{
      id?: string;
      label?: string;
      ghgProtocolMapping?: string;
      tco2e?: number;
    }>;
  }>;
}

export const Iso14064MethodologyPanel: React.FC<{
  methodology?: Iso14064Methodology | null;
  biogenicDisclosure?: Iso14064BiogenicDisclosure | null;
  iso14064?: Iso14064CategorySummary | null;
}> = ({ methodology, biogenicDisclosure, iso14064 }) => {
  if (!methodology && !biogenicDisclosure && !iso14064) {
    return null;
  }

  return (
    <Card variant="outlined">
      <CardContent>
        <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 1 }}>
          <Typography variant="h6">Methodology disclosure</Typography>
          <Chip size="small" label="In-app mirror of export" variant="outlined" />
        </Stack>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          Quantification approach, factor registry version, and biogenic treatment — aligned with the ISO 14064 PDF export.
        </Typography>

        {methodology && (
          <Stack spacing={1.5} sx={{ mb: 2 }}>
            <Typography variant="subtitle2">Quantification</Typography>
            <Box component="ul" sx={{ m: 0, pl: 2.5 }}>
              {methodology.gwpBasis && (
                <Typography component="li" variant="body2">
                  GWP basis: {methodology.gwpBasis}
                </Typography>
              )}
              {methodology.quantificationApproach && (
                <Typography component="li" variant="body2">
                  Approach: {methodology.quantificationApproach}
                </Typography>
              )}
              {methodology.reportingMode && (
                <Typography component="li" variant="body2">
                  Reporting mode: {methodology.reportingMode}
                </Typography>
              )}
              {methodology.carbonModelVersion && (
                <Typography component="li" variant="body2">
                  Carbon model: {methodology.carbonModelVersion}
                </Typography>
              )}
              {methodology.factorRegistryVersion && (
                <Typography component="li" variant="body2">
                  Factor registry: {methodology.factorRegistryVersion}
                </Typography>
              )}
            </Box>

            <Accordion disableGutters variant="outlined" sx={{ '&:before': { display: 'none' } }}>
              <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                <Typography variant="subtitle2">Transmission and distribution loss</Typography>
              </AccordionSummary>
              <AccordionDetails>
                <Typography variant="body2" paragraph>
                  Purchased grid electricity adds Scope 3 Category 3 as national Scope 2 × {(methodology.tdLoss?.lossPercent ?? 17.63)}%.
                  {' '}{methodology.tdLoss?.basis || 'Electricity lost in transformation, transmission and distribution, and electricity unaccounted, was 17.63% of electricity available in FY 2023-24.'}
                </Typography>
                <Box component="ul" sx={{ m: 0, pl: 2.5 }}>
                  <Typography component="li" variant="body2">
                    Formula: {methodology.tdLoss?.formula || 'national Scope 2 kg × 0.1763'}.
                  </Typography>
                  <Typography component="li" variant="body2">
                    Source: {methodology.tdLoss?.source || 'CEA All India Electricity Statistics, General Review 2025'}, {methodology.tdLoss?.period || 'FY 2023-24'}.
                  </Typography>
                  <Typography component="li" variant="body2">
                    Also cited in {methodology.tdLoss?.alsoCitedIn || 'CEA Growth of Electricity Sector in India (1947-2025)'}.
                  </Typography>
                  <Typography component="li" variant="body2">
                    The loss percent is multiplied directly. On-site renewable generation has no T&amp;D add-on.
                  </Typography>
                  <Typography component="li" variant="body2">
                    Fuel well-to-tank is quantity × the cited factor. It is not a percent of combustion and it is not an electricity loss.
                  </Typography>
                </Box>
                {methodology.feraModeling?.doubleCountingPrevention && (
                  <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                    {methodology.feraModeling.doubleCountingPrevention}
                  </Typography>
                )}
              </AccordionDetails>
            </Accordion>

            {(methodology.limitations || []).length > 0 && (
              <Accordion disableGutters variant="outlined" sx={{ '&:before': { display: 'none' } }}>
                <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                  <Typography variant="subtitle2">Known limitations</Typography>
                </AccordionSummary>
                <AccordionDetails>
                  <Box component="ul" sx={{ m: 0, pl: 2.5 }}>
                    {(methodology.limitations || []).map((line) => (
                      <Typography key={line} component="li" variant="body2" sx={{ mb: 0.5 }}>
                        {line}
                      </Typography>
                    ))}
                  </Box>
                </AccordionDetails>
              </Accordion>
            )}
          </Stack>
        )}

        {biogenicDisclosure && (
          <Stack spacing={0.5} sx={{ mb: 2 }}>
            <Typography variant="subtitle2">Biogenic CO₂</Typography>
            <Typography variant="body2">
              {biogenicDisclosure.treatment || 'Biogenic emissions reported separately from fossil inventory totals.'}
            </Typography>
            {biogenicDisclosure.note && (
              <Typography variant="caption" color="text.secondary">
                {biogenicDisclosure.note}
              </Typography>
            )}
          </Stack>
        )}

        {iso14064?.categories && iso14064.categories.length > 0 && (
          <Stack spacing={1}>
            <Typography variant="subtitle2">
              ISO 14064-1:2018 Clause 5.2.4 categories ({iso14064.standard || 'ISO 14064-1:2018'})
            </Typography>
            {iso14064.dualReportingNote && (
              <Typography variant="caption" color="text.secondary" display="block">
                {iso14064.dualReportingNote}
              </Typography>
            )}
            <Stack spacing={1.25} sx={{ mt: 1 }}>
              {iso14064.categories.map((category) => (
                <Box key={category.id || category.label}>
                  <Typography variant="body2" sx={{ fontWeight: 700 }}>
                    {category.label}: {Number(category.tco2e || 0).toFixed(3)} tCO₂e
                  </Typography>
                  <Typography variant="caption" color="text.secondary" display="block">
                    {category.ghgProtocolMapping || category.clause}
                  </Typography>
                  {(category.subcategories || []).length > 0 && (
                    <Box component="ul" sx={{ m: 0, mt: 0.5, pl: 2.5 }}>
                      {category.subcategories?.map((sub) => (
                        <Typography key={sub.id || sub.label} component="li" variant="caption" display="block">
                          {sub.label}: {Number(sub.tco2e || 0).toFixed(3)} tCO₂e
                          {sub.ghgProtocolMapping ? ` — ${sub.ghgProtocolMapping}` : ''}
                        </Typography>
                      ))}
                    </Box>
                  )}
                </Box>
              ))}
            </Stack>
          </Stack>
        )}
      </CardContent>
    </Card>
  );
};

export default Iso14064MethodologyPanel;
