/** Display names for BRSR field keys. Stored keys are unchanged. */
const BRSR_FIELD_DISPLAY_LABELS: Record<string, string> = {
  companyName: 'Company legal name',
  industry: 'Industry sector',
  businessDomain: 'Business domain',
  registrationsDisclosed: 'GST / Udyam / PAN registration',
  turnoverDisclosed: 'Annual turnover',
  employeeCountDisclosed: 'Employee count',
  reportingPeriod: 'Reporting period dates',
  organizationalBoundaryDocumented: 'Organizational boundary',
  operationalBoundaryDocumented: 'Operational boundary',
  totalCO2Emissions: 'Total GHG inventory',
  scope1Disclosed: 'Scope 1 emissions',
  scope2Disclosed: 'Scope 2 emissions',
  scope3Disclosed: 'Scope 3 emissions',
  scope1: 'Scope 1 emissions',
  scope2: 'Scope 2 emissions',
  scope3: 'Scope 3 emissions',
};

const humanizeBrsrFieldKey = (key: string): string => {
  const spaced = key
    .replace(/[_-]+/g, ' ')
    .replace(/([a-z\d])([A-Z])/g, '$1 $2')
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2')
    .replace(/\s+/g, ' ')
    .trim();
  if (!spaced) return key;
  return spaced.charAt(0).toUpperCase() + spaced.slice(1);
};

export const brsrFieldDisplayLabel = (key: string): string => {
  const trimmed = String(key || '').trim();
  if (!trimmed) return key;
  return BRSR_FIELD_DISPLAY_LABELS[trimmed] || humanizeBrsrFieldKey(trimmed);
};

/** Rewrites known keys inside a sentence. Other words stay as written. */
export const formatBrsrIndicatorText = (text: string): string => String(text || '').replace(
  /[A-Za-z][A-Za-z0-9_]*/g,
  (token) => {
    if (BRSR_FIELD_DISPLAY_LABELS[token]) return BRSR_FIELD_DISPLAY_LABELS[token];
    if (/[a-z][A-Z]/.test(token) || token.includes('_')) return humanizeBrsrFieldKey(token);
    return token;
  }
);
